use error::LexError;
use std::fmt::{Debug, Write};
use std::hint::black_box;
use std::time::Instant;

/// Renders everything observable about a stream: each item, the end, and what a call after the end yields.
fn render<T: Debug, I: Iterator<Item = Result<T, LexError>>>(mut it: I) -> String {
    let mut out = String::new();
    let mut steps = 0;
    while let Some(item) = it.next() {
        write!(out, "{:?};", item).unwrap();
        steps += 1;
        assert!(steps < 10_000, "stream does not end");
    }
    write!(out, "|end|{:?}|{:?}", it.next(), it.next()).unwrap();
    out
}

fn check(line: &str, failures: &mut u64, checked: &mut u64) {
    *checked += 1;
    let old = render(old_token::tokenize(line));
    let new = render(new_token::tokenize(line));
    if old != new {
        *failures += 1;
        if *failures <= 10 {
            println!("MISMATCH on {line:?}\n  old: {old}\n  new: {new}");
        }
    }
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // xorshift64*
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

const ALPHABET: &[&str] = &["[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "t", "é"];

fn exhaustive(max_len: usize, failures: &mut u64, checked: &mut u64) {
    // Every string over ALPHABET up to max_len symbols.
    let mut stack: Vec<String> = vec![String::new()];
    while let Some(s) = stack.pop() {
        check(&s, failures, checked);
        if s.len() < max_len * 2 {
