        let symbols = s.chars().count();
        if symbols < max_len {
            // push extensions in reverse so the order is deterministic
            for sym in ALPHABET.iter().rev() {
                let mut t = s.clone();
                t.push_str(sym);
                stack.push(t);
            }
        }
    }
}

