        "msg=\"disk 91% full\"",
        "msg=\"say \\\"hi\\\"\\n\"",
        "msg=\"\"",
        "started",
        "worker-3",
        "=x",
        "a=b=c",
        "\"q\"",
        "[bad",
        "x=\"open",
        "é=ü",
        "k=\"a\\qb\"",
