            new_sum = black_box(count_tokens!(new_token, lines.iter().map(|s| s.as_str())));
            new_times.push(t.elapsed().as_secs_f64());
        } else {
            let t = Instant::now();
            new_sum = black_box(count_tokens!(new_token, lines.iter().map(|s| s.as_str())));
            new_times.push(t.elapsed().as_secs_f64());
            let t = Instant::now();
            old_sum = black_box(count_tokens!(old_token, lines.iter().map(|s| s.as_str())));
            old_times.push(t.elapsed().as_secs_f64());
        }
