        old_med * 1e3,
        bytes as f64 / 1e6 / old_med,
        new_med * 1e3,
        bytes as f64 / 1e6 / new_med,
        new_med / old_med,
    );
    println!("bench old times ms: {:?}", old_times.iter().map(|t| (t * 1e3).round()).collect::<Vec<_>>());
    println!("bench new times ms: {:?}", new_times.iter().map(|t| (t * 1e3).round()).collect::<Vec<_>>());
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_else(|| "check".into());
    if mode == "check" {
        let (mut failures, mut checked) = (0u64, 0u64);
        let max_len: usize = std::env::args().nth(2).and_then(|s| s.parse().ok()).unwrap_or(6);
        exhaustive(max_len, &mut failures, &mut checked);
        println!("exhaustive up to {max_len} symbols: checked {checked}, mismatches {failures}");

        let (mut f2, mut c2) = (0u64, 0u64);
        let mut rng = Rng(0xDEAD_BEEF_CAFE_F00D);
        for _ in 0..300_000 {
            let line = random_line(&mut rng);
            check(&line, &mut f2, &mut c2);
        }
        for _ in 0..200_000 {
            let len = rng.below(120);
            let mut s = String::new();
            for _ in 0..len {
                s.push_str(ALPHABET[rng.below(ALPHABET.len())]);
            }
            check(&s, &mut f2, &mut c2);
        }
        println!("random: checked {c2}, mismatches {f2}");
        if failures + f2 > 0 {
            std::process::exit(1);
        }
    } else {
        let corpus = build_bench_corpus(1_000_000);
        bench(&corpus);
    }
}

