    // Variants: 0 = HEAD original, 1 = control copy of HEAD, 2 = refactor with #[inline], 3 = refactor without it.
    const NAMES: [&str; 4] = ["old(HEAD)", "old(control)", "new(inline)", "new(noinline)"];
    let reps = 15;
    let mut times: [Vec<f64>; 4] = Default::default();
    let mut sums = [0u64; 4];
    let lines: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
    for rep in 0..reps {
        // Rotate the starting variant each round so warm-up and frequency drift do not favour one side.
        for k in 0..4 {
            let v = (rep + k) % 4;
            let t = Instant::now();
            sums[v] = black_box(match v {
                0 => count_tokens!(old_token, lines.iter().copied()),
                1 => count_tokens!(old_copy_token, lines.iter().copied()),
                2 => count_tokens!(new_token, lines.iter().copied()),
                _ => count_tokens!(new_noinline, lines.iter().copied()),
            });
            times[v].push(t.elapsed().as_secs_f64());
        }
    }
    assert!(sums.iter().all(|&s| s == sums[0]), "bench checksums differ: {sums:?}");
    let mb = lines.iter().map(|l| l.len()).sum::<usize>() as f64 / 1e6;
    println!("bench: {} lines, {mb:.1} MB, {reps} rounds, tokens checksum {}", lines.len(), sums[0]);
    let base = {
        let mut t = times[0].clone();
        median(&mut t)
    };
    for (v, name) in NAMES.iter().enumerate() {
        let mut t = times[v].clone();
        let min = t.iter().cloned().fold(f64::INFINITY, f64::min);
        let med = median(&mut t);
        println!(
            "{name:<13} min {:7.1} ms  median {:7.1} ms ({:4.0} MB/s)  median vs old(HEAD) {:.3}",
            min * 1e3,
            med * 1e3,
            mb / med,
            med / base
        );
    }
}

