use error::LexError;
use std::fmt::{Debug, Write};
use std::hint::black_box;
use std::time::Instant;

/// Renders everything observable about a stream: each item, the end, and what calls after the end yield.
fn render<T: Debug, I: Iterator<Item = Result<T, LexError>>>(mut it: I) -> String {
    let mut out = String::new();
    let mut steps = 0;
    while let Some(item) = it.next() {
        write!(out, "{:?};", item).unwrap();
        steps += 1;
        assert!(steps < 10_000, "stream does not end");
    }
    write!(out, "|end|{:?}|{:?}", it.next(), it.next()).unwrap();
    out
}

fn check(line: &str, failures: &mut u64, checked: &mut u64) {
    *checked += 1;
    let old = render(old_token::tokenize(line));
    let new = render(new_token::tokenize(line));
    if old != new {
        *failures += 1;
        if *failures <= 10 {
            println!("MISMATCH on {line:?}\n  old: {old}\n  new: {new}");
        }
    }
}

struct Rng(u64);
impl Rng {
    fn next_u64(&mut self) -> u64 {
        // xorshift64*
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }
}

const ALPHABET: &[&str] = &["[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "t", "é"];

/// Every string made of up to `max_symbols` symbols from ALPHABET.
fn exhaustive(max_symbols: usize, failures: &mut u64, checked: &mut u64) {
    let mut stack: Vec<(String, usize)> = vec![(String::new(), 0)];
    while let Some((s, symbols)) = stack.pop() {
        check(&s, failures, checked);
        if symbols < max_symbols {
            for sym in ALPHABET.iter().rev() {
                stack.push((format!("{s}{sym}"), symbols + 1));
            }
        }
    }
}

/// Mostly well-formed pieces, with occasional random symbols so error paths are exercised too.
fn random_line(rng: &mut Rng) -> String {
    const PIECES: &[&str] = &[
        "[2024-05-01T12:00:00Z]",
        "[]",
        "level=info",
        "user=ann",
        "retries=",
        "msg=\"disk 91% full\"",
        "msg=\"say \\\"hi\\\"\\n\"",
        "msg=\"\"",
        "started",
        "worker-3",
        "=x",
        "a=b=c",
        "\"q\"",
        "[bad",
        "x=\"open",
        "é=ü",
        "k=\"a\\qb\"",
    ];
    const SEPARATORS: &[&str] = &[" ", "\t", "  ", "", " \t "];
    let mut s = String::new();
    for _ in 0..rng.below(8) {
        s.push_str(PIECES[rng.below(PIECES.len())]);
        s.push_str(SEPARATORS[rng.below(SEPARATORS.len())]);
    }
    for _ in 0..rng.below(3) {
        let at = rng.below(s.len() + 1);
        if s.is_char_boundary(at) {
            s.insert_str(at, ALPHABET[rng.below(ALPHABET.len())]);
        }
    }
    s
}

fn build_bench_corpus(lines: usize) -> Vec<String> {
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    (0..lines)
        .map(|i| {
            format!(
                "[2024-05-01T12:{:02}:{:02}Z] level={} msg=\"request {} took {}ms\" user=u{} retries= done {}",
                i % 60,
                (i / 60) % 60,
                ["info", "warn", "error", "debug"][rng.below(4)],
                i,
                rng.below(9000),
                rng.below(500),
                rng.below(10_000),
            )
        })
        .collect()
}

macro_rules! count_tokens {
    ($module:ident, $lines:expr) => {{
        let mut n: u64 = 0;
        for line in $lines {
            for token in $module::tokenize(line) {
                match token {
                    Ok($module::Token::Key(s)) => n += s.len() as u64,
                    Ok(_) => n += 1,
                    Err(_) => n += 3,
                }
            }
        }
        n
    }};
}

fn median(v: &mut [f64]) -> f64 {
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    v[v.len() / 2]
}

fn bench(lines: &[String]) {
    let reps = 9;
    let (mut old_times, mut new_times) = (Vec::new(), Vec::new());
    let (mut old_sum, mut new_sum) = (0, 0);
    for rep in 0..reps {
        // Alternate the order so warm-up and frequency drift do not favour one side.
        let run_old = |sum: &mut u64| {
            let t = Instant::now();
            *sum = black_box(count_tokens!(old_token, lines.iter().map(|s| s.as_str())));
            t.elapsed().as_secs_f64()
        };
        let run_new = |sum: &mut u64| {
            let t = Instant::now();
            *sum = black_box(count_tokens!(new_token, lines.iter().map(|s| s.as_str())));
            t.elapsed().as_secs_f64()
        };
        if rep % 2 == 0 {
            old_times.push(run_old(&mut old_sum));
            new_times.push(run_new(&mut new_sum));
        } else {
            new_times.push(run_new(&mut new_sum));
            old_times.push(run_old(&mut old_sum));
        }
    }
    assert_eq!(old_sum, new_sum, "bench checksums differ");
    let mb = lines.iter().map(|l| l.len()).sum::<usize>() as f64 / 1e6;
    let (old_med, new_med) = (median(&mut old_times), median(&mut new_times));
    println!(
        "bench: {} lines, {mb:.1} MB, tokens checksum {old_sum}",
        lines.len()
    );
    println!("old: median {:.1} ms ({:.0} MB/s)", old_med * 1e3, mb / old_med);
    println!("new: median {:.1} ms ({:.0} MB/s)", new_med * 1e3, mb / new_med);
    println!("new/old median ratio = {:.3}", new_med / old_med);
    println!("old ms: {:?}", old_times.iter().map(|t| (t * 1e3).round()).collect::<Vec<_>>());
    println!("new ms: {:?}", new_times.iter().map(|t| (t * 1e3).round()).collect::<Vec<_>>());
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_else(|| "check".into());
    if mode == "check" {
        let max_symbols: usize = std::env::args().nth(2).and_then(|s| s.parse().ok()).unwrap_or(6);
        let (mut failures, mut checked) = (0u64, 0u64);
        exhaustive(max_symbols, &mut failures, &mut checked);
        println!("exhaustive up to {max_symbols} symbols: checked {checked}, mismatches {failures}");

        let (mut f2, mut c2) = (0u64, 0u64);
        let mut rng = Rng(0xDEAD_BEEF_CAFE_F00D);
        for _ in 0..300_000 {
            let line = random_line(&mut rng);
            check(&line, &mut f2, &mut c2);
        }
        for _ in 0..200_000 {
            let len = rng.below(120);
            let mut s = String::new();
            for _ in 0..len {
                s.push_str(ALPHABET[rng.below(ALPHABET.len())]);
            }
            check(&s, &mut f2, &mut c2);
        }
        println!("random: checked {c2}, mismatches {f2}");
        if failures + f2 > 0 {
            std::process::exit(1);
        }
    } else {
        bench(&build_bench_corpus(1_000_000));
    }
}

